INSERT INTO relation_type VALUES('exposes','exposed_by','Asset|Team','Capability',0,3,'The entity delivers this capability for the rest of the organisation.');
INSERT INTO relation_type VALUES('requires','required_by','Asset|Team','Capability',0,3,'The entity needs this capability to do its job. Something active must expose it.');
INSERT INTO relation_type VALUES('depends_on','dependents','Application','Application|Service',1,NULL,'The application calls or relies on another application or service at runtime.');
INSERT INTO property VALUES('capability','Capability','owner','ref',NULL,1,1,'Person or team accountable for the capability: its roadmap, budget and risk decisions. Set it on a domain or group and everything beneath inherits it unless it sets its own. Name a User or Team entity by its name, id or (for a User) email.');
INSERT INTO property VALUES('capability','Capability','criticality','enum','medium',1,0,'How much the business suffers when this capability is unavailable or degraded. It sets recovery targets and how closely the capability is reviewed.');
INSERT INTO property_value VALUES('capability','Capability','criticality','low',0,'Can be down for days using workarounds, with little customer or financial impact.');
INSERT INTO property_value VALUES('capability','Capability','criticality','medium',1,'Disruption hurts within a day, causing delays and manual workarounds but limited customer impact.');
INSERT INTO property_value VALUES('capability','Capability','criticality','high',2,'An outage stops core operations or causes financial, legal or customer harm within hours. Needs a recovery plan, tested failover and named on-call support.');
INSERT INTO property VALUES('capability','Capability','review_cycle_days','int','180',1,0,'Days between scheduled reviews of the capability''s owner, providers and maturity.');
INSERT INTO property VALUES('capability','Capability','maturity','enum','initial',0,0,'How well established the way of delivering this capability is.');
INSERT INTO property_value VALUES('capability','Capability','maturity','initial',0,'Ad hoc; it depends on individuals and has no documented process.');
INSERT INTO property_value VALUES('capability','Capability','maturity','pilot',1,'Being trialled in part of the organisation.');
INSERT INTO property_value VALUES('capability','Capability','maturity','defined',2,'Documented, standard process used consistently.');
INSERT INTO property_value VALUES('capability','Capability','maturity','optimized',3,'Measured and improved continuously.');
INSERT INTO property VALUES('capability','Capability','lifecycle','enum','active',0,0,'Where the capability is in its life.');
INSERT INTO property_value VALUES('capability','Capability','lifecycle','plan',0,'Planned but not delivered yet.');
INSERT INTO property_value VALUES('capability','Capability','lifecycle','active',1,'In use.');
INSERT INTO property_value VALUES('capability','Capability','lifecycle','retire',2,'Being phased out. Nothing active may sit beneath it.');
INSERT INTO property VALUES('entity_type','Asset','owner','ref',NULL,0,0,'Team or person accountable for running the asset. Name a User or Team by its name, id or (for a User) email.');
INSERT INTO property VALUES('entity_type','Asset','lifecycle','enum','active',0,0,'Where the asset is in its life.');
INSERT INTO property_value VALUES('entity_type','Asset','lifecycle','plan',0,'Planned or being built; it doesn''t provide anything yet.');
INSERT INTO property_value VALUES('entity_type','Asset','lifecycle','active',1,'In service.');
INSERT INTO property_value VALUES('entity_type','Asset','lifecycle','retire',2,'Being decommissioned. It no longer counts as a provider of capabilities.');
INSERT INTO property VALUES('entity_type','Application','vendor','string',NULL,0,0,'Supplier of the product, or "internal" for software built in-house.');
INSERT INTO property VALUES('entity_type','Team','head','ref',NULL,0,0,'Person who leads the team. Name a User by its name, id or email.');
INSERT INTO property VALUES('entity_type','Team','lifecycle','enum','active',0,0,'Whether the team exists yet, is working, or is being wound down.');
INSERT INTO property_value VALUES('entity_type','Team','lifecycle','plan',0,'Being formed.');
INSERT INTO property_value VALUES('entity_type','Team','lifecycle','active',1,'Working.');
INSERT INTO property_value VALUES('entity_type','Team','lifecycle','retire',2,'Being wound down. It no longer counts as a provider of capabilities.');
INSERT INTO property VALUES('entity_type','User','email','string',NULL,0,1,'Primary email address, used as the person''s sign-in and contact address. It is a key: unique across users, and a reference to a User may use it instead of the name.');
INSERT INTO property VALUES('entity_type','User','lifecycle','enum','active',0,0,'Where the person''s account is in its life.');
INSERT INTO property_value VALUES('entity_type','User','lifecycle','plan',0,'Being onboarded; the account is not in use yet.');
INSERT INTO property_value VALUES('entity_type','User','lifecycle','active',1,'Account in use.');
INSERT INTO property_value VALUES('entity_type','User','lifecycle','retire',2,'Offboarded; the account is disabled.');
INSERT INTO property VALUES('relation_type','exposes','coverage','enum','full',0,0,'How much of the capability this entity delivers.');
INSERT INTO property_value VALUES('relation_type','exposes','coverage','full',0,'Delivers the whole capability.');
INSERT INTO property_value VALUES('relation_type','exposes','coverage','partial',1,'Delivers only part of it; another provider is needed for the rest.');
INSERT INTO property VALUES('relation_type','requires','dependency','enum','hard',0,0,'What happens to the entity when nothing provides the capability.');
INSERT INTO property_value VALUES('relation_type','requires','dependency','hard',0,'It cannot operate. An unmet hard requirement is a break.');
INSERT INTO property_value VALUES('relation_type','requires','dependency','soft',1,'It keeps running in a degraded way.');
INSERT INTO property VALUES('relation_type','depends_on','criticality','enum','medium',0,0,'How badly the application suffers when the dependency fails.');
INSERT INTO property_value VALUES('relation_type','depends_on','criticality','low',0,'Hardly noticed, or easily worked around.');
INSERT INTO property_value VALUES('relation_type','depends_on','criticality','medium',1,'Some features fail; the rest keeps working.');
INSERT INTO property_value VALUES('relation_type','depends_on','criticality','high',2,'The application stops working.');
