PRAGMA foreign_keys=ON;
-- capability.owner: Person or team accountable for the capability: its roadmap, budget and risk decisions. Set it on a domain or group and everything beneath inherits it unless it sets its own. Name a User or Team entity by its name, id or (for a User) email.
-- capability.criticality: How much the business suffers when this capability is unavailable or degraded. It sets recovery targets and how closely the capability is reviewed.
-- capability.review_cycle_days: Days between scheduled reviews of the capability's owner, providers and maturity.
-- capability.maturity: How well established the way of delivering this capability is.
-- capability.lifecycle: Where the capability is in its life.
CREATE TABLE capability(id INTEGER PRIMARY KEY, uid TEXT UNIQUE, path TEXT UNIQUE NOT NULL, name TEXT NOT NULL, parent_id INTEGER REFERENCES capability(id), level INTEGER NOT NULL, owner TEXT, criticality TEXT, review_cycle_days INTEGER, maturity TEXT, lifecycle TEXT);
CREATE TABLE entity_type(name TEXT PRIMARY KEY, parent TEXT REFERENCES entity_type(name), description TEXT);
CREATE TABLE entity(id INTEGER PRIMARY KEY, uid TEXT UNIQUE, name TEXT UNIQUE NOT NULL, type TEXT NOT NULL REFERENCES entity_type(name), props TEXT NOT NULL DEFAULT '{}');
CREATE TABLE relation_type(name TEXT PRIMARY KEY, inverse TEXT, from_types TEXT, to_types TEXT, transitive INTEGER, min_level INTEGER, description TEXT);
CREATE TABLE property(owner_kind TEXT NOT NULL, owner TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, default_value TEXT, inherit INTEGER, required INTEGER, description TEXT, PRIMARY KEY(owner_kind, owner, name));
CREATE TABLE property_value(owner_kind TEXT NOT NULL, owner TEXT NOT NULL, property TEXT NOT NULL, value TEXT NOT NULL, ord INTEGER NOT NULL, description TEXT, PRIMARY KEY(owner_kind, owner, property, value), FOREIGN KEY(owner_kind, owner, property) REFERENCES property(owner_kind, owner, name));
CREATE TABLE link(id INTEGER PRIMARY KEY, src INTEGER NOT NULL REFERENCES entity(id), relation TEXT NOT NULL REFERENCES relation_type(name), cap_id INTEGER REFERENCES capability(id), ent_id INTEGER REFERENCES entity(id), attrs TEXT NOT NULL DEFAULT '{}', CHECK((cap_id IS NULL) <> (ent_id IS NULL)));
CREATE INDEX link_rel ON link(relation, cap_id);
CREATE VIEW entity_active AS SELECT * FROM entity WHERE COALESCE(json_extract(props,'$.lifecycle'),'active')<>'retire';
CREATE VIEW unmet_requires AS SELECT e.name AS entity, c.path AS capability, json_extract(l.attrs,'$.dependency') AS severity
  FROM link l JOIN entity_active e ON e.id=l.src JOIN capability c ON c.id=l.cap_id WHERE l.relation='requires' AND NOT EXISTS (
    SELECT 1 FROM link p JOIN entity_active pe ON pe.id=p.src JOIN capability pc ON pc.id=p.cap_id
    WHERE p.relation IN ('exposes') AND pe.id<>l.src AND (pc.path=c.path OR pc.path LIKE c.path||'/%'));
CREATE VIEW coverage AS SELECT c.path, c.level, (SELECT COUNT(DISTINCT p.src) FROM link p JOIN entity_active pe ON pe.id=p.src JOIN capability pc ON pc.id=p.cap_id
  WHERE p.relation IN ('exposes') AND (pc.path=c.path OR pc.path LIKE c.path||'/%')) AS providers FROM capability c WHERE c.level>=3;
CREATE VIEW depends_on_closure AS WITH RECURSIVE r(src,dst) AS (SELECT src,ent_id FROM link WHERE relation='depends_on' AND ent_id IS NOT NULL
  UNION SELECT r.src,l.ent_id FROM r JOIN link l ON l.src=r.dst WHERE l.relation='depends_on' AND l.ent_id IS NOT NULL)
  SELECT a.name AS src, b.name AS dst FROM r JOIN entity a ON a.id=r.src JOIN entity b ON b.id=r.dst;
